css:
.cd-card{border:1px solid var(--cd-border);border-radius:var(--cd-radius);background:var(--cd-surface);transition:transform var(--cd-duration) ease,border-color var(--cd-duration) ease,box-shadow var(--cd-duration) ease}
.cd-card:hover{border-color:var(--cd-accent);box-shadow:0 0 0 1px var(--cd-accent),0 0 18px var(--cd-accent);transform:translateY(-2px)}
.cd-card-thumb{border-radius:2px}
.cd-card-title{text-transform:uppercase;letter-spacing:0.04em;font-weight:700;font-size:0.9em}
.cd-card-meta{letter-spacing:0.03em;color:var(--cd-muted)}
.cd-card-duration{background:var(--cd-accent);color:var(--cd-accent-text);border-radius:2px;font-weight:700}
.cd-row-title{text-transform:uppercase;letter-spacing:0.12em;text-shadow:0 0 10px var(--cd-accent)}
.cd-hero-title{text-transform:uppercase;letter-spacing:0.06em;text-shadow:0 0 14px var(--cd-accent)}
.cd-hero-cta{background:var(--cd-accent);color:var(--cd-accent-text);box-shadow:0 0 16px var(--cd-accent);border-radius:var(--cd-radius)}
